        assertEquals(3, h.size());
    }

    @Test void testRecentWithLimitOne() {
        var h = new ActivityHistory(3);
        h.append(e("minecraft:a"));
        h.append(e("minecraft:b"));
        h.append(e("minecraft:c"));
        assertEquals(List.of(e("minecraft:c")), h.recent(1));
        assertEquals(3, h.size());
    }

    @Test void testRecentWithLimitGreaterThanCapacity() {
        var h = new ActivityHistory(3);
        h.append(e("minecraft:a"));
        h.append(e("minecraft:b"));
        h.append(e("minecraft:c"));
        assertEquals(List.of(e("minecraft:c"), e("minecraft:b"), e("minecraft:a")), h.recent(5));
        assertEquals(3, h.size());
    }

    @Test void testRecentWithZeroLimit() {
        var h = new ActivityHistory(3);
        assertThrows(IllegalArgumentException.class, () -> h.recent(0));
    }

    @Test void testRecentWithNegativeLimit() {
        var h = new ActivityHistory(3);
        assertThrows(IllegalArgumentException.class, () -> h.recent(-1));
    }
"
